// EITS Payment Report - Image Preview Custom Script

frappe.query_reports["EITS Payment"] = {
    "formatter": function (value, row, column, data, default_formatter) {
        // Check if this is the Image column
        if (column.fieldname === "image" || column.label === "Image (Image Attachments)") {
            if (value && value.includes('/files/')) {
                // Create clickable link for image
                return `<a href="#" onclick="showImagePreview('${value}')" style="color: #007bff; text-decoration: underline;">
                    ${value.split('/').pop()}
                </a>`;
            }
        }
        return default_formatter(value, row, column, data);
    }
};

// Function to show image preview popup
function showImagePreview(imageUrl) {
    // Create modal dialog
    let modal = new frappe.ui.Dialog({
        title: 'Image Preview',
        size: 'large',
        fields: [
            {
                fieldtype: 'HTML',
                fieldname: 'image_preview',
                options: `
                    <div style="text-align: center; padding: 20px;">
                        <img src="${imageUrl}" 
                             style="max-width: 100%; max-height: 500px; border: 1px solid #ddd; border-radius: 8px;"
                             onerror="this.style.display='none'; this.nextElementSibling.style.display='block';">
                        <div style="display: none; padding: 50px; color: #999;">
                            <i class="fa fa-image" style="font-size: 48px;"></i><br>
                            Image could not be loaded
                        </div>
                    </div>
                `
            }
        ],
        primary_action_label: 'Download',
        primary_action: function() {
            // Download image
            window.open(imageUrl, '_blank');
        },
        secondary_action_label: 'Close'
    });
    
    modal.show();
}

// Alternative: Add click handler after report loads
$(document).on('page-change', function() {
    setTimeout(function() {
        // Add click handlers to image URLs
        $('.dt-cell__content').each(function() {
            let cell = $(this);
            let text = cell.text().trim();
            
            if (text.includes('/files/') && (text.includes('.jpg') || text.includes('.jpeg') || text.includes('.png') || text.includes('.gif'))) {
                cell.css({
                    'color': '#007bff',
                    'cursor': 'pointer',
                    'text-decoration': 'underline'
                }).on('click', function() {
                    showImagePreview(text);
                });
            }
        });
    }, 1000);
});

